(*主卡进给轴自整定*)
CASE nMoveSelfTuningState OF 
  0:
    IF bMoveSelfTuningStart THEN
      nMoveSelfTuningState := 10;
      bMoveSelfTuningStart := FALSE;
      g_bMiddleFeedAxisSelfTuningDone := FALSE;
    END_IF;
    IF bMiddleAxisSelfTuningStart THEN
      nMoveSelfTuningState := 100;
      bMiddleAxisSelfTuningStart := FALSE;
      g_bMiddleAvoidAxisSelfTuningDone := FALSE;
    END_IF;
  10:
    g_MiddleAvoidFeedAxisSelfTuning.EXECUTE := TRUE;
    g_MiddleAvoidFeedAxisSelfTuning.DIRECTION :=1;
    IF g_MiddleAvoidFeedAxisSelfTuning.DONE THEN
      g_MiddleAvoidFeedAxisSelfTuning.EXECUTE := FALSE;
      g_dMiddleFeedAxisSelfSelfTuningCF := g_MiddleAvoidFeedAxisSelfTuning.CF_POSITIVE;
      nMoveSelfTuningState := 0;
      g_bMiddleFeedAxisSelfTuningDone := TRUE;
    END_IF;
    IF g_MiddleAvoidFeedAxisSelfTuning.COMMANDABORTED OR g_MiddleAvoidFeedAxisSelfTuning.ERROR THEN
      nMoveSelfTuningState := 20;
      g_MiddleAvoidFeedAxisSelfTuning.EXECUTE := FALSE;
    END_IF;
    IF  g_bPlcResetBuffer THEN
      nMoveSelfTuningState := 20;
    END_IF;

  20:
      g_AntiRejection4Stop.Execute := TRUE;
      IF g_AntiRejection4Stop.Done  THEN
        g_AntiRejection4Stop.Execute := FALSE;
        nMoveSelfTuningState := 0;
      END_IF;
      IF g_AntiRejection4Stop.CommandAborted OR g_AntiRejection4Stop.Error THEN
        g_AntiRejection4Stop.Execute := FALSE;
        nMoveSelfTuningState := 0;
      END_IF;
    IF g_bPlcResetBuffer THEN
      g_AntiRejection4Stop.Execute := FALSE;
      nMoveSelfTuningState := 0;
    END_IF;
  100:(*中卡避让轴自整定*)
    g_MiddleAvoidAxisSelfTuning.EXECUTE := TRUE;
    g_MiddleAvoidAxisSelfTuning.DIRECTION :=1;
    IF g_MiddleAvoidAxisSelfTuning.DONE THEN
      g_MiddleAvoidAxisSelfTuning.EXECUTE := FALSE;
      g_dMiddleAvoidAxisSelfTuningCF := g_MiddleAvoidAxisSelfTuning.CF_POSITIVE;
      nMoveSelfTuningState := 0;
      g_bMiddleAvoidAxisSelfTuningDone := TRUE;
    END_IF;
    IF g_MiddleAvoidAxisSelfTuning.COMMANDABORTED OR g_MiddleAvoidAxisSelfTuning.ERROR THEN
      nMoveSelfTuningState := 200;
      g_MiddleAvoidAxisSelfTuning.EXECUTE := FALSE;
    END_IF;
    IF  g_bPlcResetBuffer THEN
      nMoveSelfTuningState := 200;
    END_IF;

  200:
      g_AntiRejection5Stop.Execute := TRUE;
      IF g_AntiRejection5Stop.Done  THEN
        g_AntiRejection5Stop.Execute := FALSE;
        nMoveSelfTuningState := 0;
      END_IF;
      IF g_AntiRejection5Stop.CommandAborted OR g_AntiRejection5Stop.Error THEN
        g_AntiRejection5Stop.Execute := FALSE;
        nMoveSelfTuningState := 0;
      END_IF;
    IF g_bPlcResetBuffer THEN
      g_AntiRejection5Stop.Execute := FALSE;
      nMoveSelfTuningState := 0;
    END_IF;
END_CASE;








IF g_bPlcResetBuffer THEN
  g_MiddleAvoidFeedAxisSelfTuning.EXECUTE := FALSE;
  g_bMiddleFeedAxisSelfTuningDone := FALSE;
  g_bMiddleAvoidAxisSelfTuningDone := FALSE; 
  g_AntiRejection5Stop.Execute := FALSE;
  g_AntiRejection4Stop.Execute := FALSE;
  nMoveSelfTuningState := 0;
  bMoveSelfTuningStart := FALSE;
  bMiddleAxisSelfTuningStart := FALSE;
END_IF;
